//! Target A — multi-limb addition, `crypto_bigint::U256::wrapping_add`.
//!
//! The first target because it has no input-domain complications: it is
//! defined for every pair of 256-bit values, so unrestricted generated byte
//! arrays are valid operands and a finding cannot be an artifact of feeding
//! the operation inputs its mathematics does not admit.

use crate::sink::{consume_all_bytes, result_array};
use crypto_bigint::U256;
use trace_check_macros::constant_time;

/// `left + right mod 2^256`, as the **complete** 32-byte result.
///
/// Shared by both adapters below and by the functional tests, so the tests
/// validate the same code the contracts analyze rather than a parallel
/// implementation of it. They have to compare the whole result: the sink maps
/// 2^256 results onto 256 values and two byte changes can cancel exactly, so a
/// test comparing through it cannot establish that a mutation preserved the
/// arithmetic.
///
/// `#[inline(always)]` so the compiled adapter keeps the shape
/// `docs/audits/crypto-bigint/findings.md` describes from its disassembly.
#[inline(always)]
pub fn wrapping_add_bytes(left: &[u8; 32], right: &[u8; 32]) -> [u8; 32] {
    let a = U256::from_be_slice(left);
    let b = U256::from_be_slice(right);
    result_array(a.wrapping_add(&b).to_be_bytes().as_slice())
}

/// Per-contract discriminants, and why they exist.
///
/// The two adapters below differ only in which parameters are *declared*
/// secret, and a declaration does not change codegen — so written without
/// these they compiled to bit-identical bodies and both symbols were folded to
/// one address. Valgrind then named whichever symbol survived, and the first
/// run of a mutated dependency reported `INCONCLUSIVE — 8 finding(s) … none
/// attributable to wrapping_add_secret_left` for a leak that was genuinely
/// there and genuinely reached.
///
/// One `xor` with a compile-time constant is enough to keep the bodies
/// distinct. It has no branch and no address dependency, so it cannot change
/// what the contract observes; `docs/audits/crypto-bigint/integration-report.md`
/// records the measurement.
pub const SECRET_LEFT_TAG: u8 = 0x5a;
pub const BOTH_SECRET_TAG: u8 = 0xa5;

/// `left + right mod 2^256`, with `left` secret and `right` public.
///
/// The adapter decodes big-endian bytes with the library's own
/// `from_be_slice`, calls the library's own `wrapping_add`, and folds the whole
/// result. It contains no arithmetic of its own.
#[constant_time(secret = "left", dynamic = false)]
pub fn wrapping_add_secret_left(left: &[u8; 32], right: &[u8; 32]) -> u8 {
    consume_all_bytes(&wrapping_add_bytes(left, right)) ^ SECRET_LEFT_TAG
}

/// The same operation with **both** operands secret.
///
/// A separate contract rather than a parameter, because it is a different
/// security requirement: an implementation may be safe for a public operand
/// and not for a secret one, and the declaration is what records which claim
/// was checked.
#[constant_time(secret = "left", secret = "right", dynamic = false)]
pub fn wrapping_add_both_secret(left: &[u8; 32], right: &[u8; 32]) -> u8 {
    consume_all_bytes(&wrapping_add_bytes(left, right)) ^ BOTH_SECRET_TAG
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The adapter agrees with an independent big-integer reduction mod
    /// 2^256 on the boundary cases carry propagation turns on.
    #[test]
    fn the_adapter_computes_wrapping_addition() {
        for (left, right) in [
            ([0u8; 32], [0u8; 32]),
            ([0u8; 32], [0xff; 32]),
            ([0xff; 32], [0xff; 32]),
        ] {
            let expected = reference_wrapping_add(&left, &right);
            // Full width, against the schoolbook reference.
            assert_eq!(wrapping_add_bytes(&left, &right), expected);
            // And the adapter is that helper plus its discriminant.
            assert_eq!(
                wrapping_add_secret_left(&left, &right),
                consume_all_bytes(&expected) ^ SECRET_LEFT_TAG
            );
        }
    }

    /// Both roles compute the same sum, differing only by the documented
    /// per-contract discriminant: the secret declaration changes what is
    /// claimed, never what is computed.
    #[test]
    fn both_secret_roles_compute_the_same_sum() {
        let left = [0x5au8; 32];
        let right = [0xa5u8; 32];
        assert_eq!(
            wrapping_add_secret_left(&left, &right) ^ SECRET_LEFT_TAG,
            wrapping_add_both_secret(&left, &right) ^ BOTH_SECRET_TAG
        );
    }

    /// The discriminants are distinct, which is the whole reason they exist:
    /// equal tags would restore the bit-identical bodies that defeated
    /// per-contract attribution.
    #[test]
    fn the_contract_discriminants_differ() {
        assert_ne!(SECRET_LEFT_TAG, BOTH_SECRET_TAG);
    }

    /// A carry out of the lowest limb reaches the next one, which is the
    /// behavior a per-limb adapter bug would silently lose.
    #[test]
    fn a_carry_crosses_the_limb_boundary() {
        let mut left = [0u8; 32];
        left[24..].copy_from_slice(&[0xff; 8]);
        let mut right = [0u8; 32];
        right[31] = 1;
        let sum = reference_wrapping_add(&left, &right);
        assert_eq!(sum[23], 1, "the carry must land in the next limb");
        assert_eq!(&sum[24..], &[0u8; 8], "the low limb must wrap to zero");
        assert_eq!(wrapping_add_bytes(&left, &right), sum);
        assert_eq!(
            wrapping_add_secret_left(&left, &right),
            consume_all_bytes(&sum) ^ SECRET_LEFT_TAG
        );
    }

    /// Schoolbook big-endian addition mod 2^256, written independently of
    /// `crypto-bigint`, so a byte-order or truncation mistake in the adapter
    /// does not cancel out against the implementation under audit.
    fn reference_wrapping_add(left: &[u8; 32], right: &[u8; 32]) -> [u8; 32] {
        let mut sum = [0u8; 32];
        let mut carry = 0u16;
        for index in (0..32).rev() {
            let total = u16::from(left[index]) + u16::from(right[index]) + carry;
            sum[index] = total as u8;
            carry = total >> 8;
        }
        sum
    }
}
